/* Generates src/text/grapheme_data.c from the Unicode data files in
 * third_party/unicode. Run by hand when the Unicode version changes:
 *   cc -o gen_grapheme tools/gen_grapheme.c && ./gen_grapheme third_party/unicode > src/text/grapheme_data.c
 * The generated file is committed, so the normal build never runs this. */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct { unsigned lo, hi; int v; } R;
typedef struct { R *r; int n, cap; } List;

static void add(List *l, unsigned lo, unsigned hi, int v) {
    if (l->n == l->cap) { l->cap = l->cap ? l->cap * 2 : 256; l->r = realloc(l->r, (size_t)l->cap * sizeof(R)); }
    l->r[l->n].lo = lo; l->r[l->n].hi = hi; l->r[l->n].v = v; l->n++;
}
static int cmp(const void *a, const void *b) {
    unsigned x = ((const R *)a)->lo, y = ((const R *)b)->lo;
    return x < y ? -1 : x > y;
}

/* Reads "LO[..HI] ; <name> # ..." lines; keeps those where `want` (a property
 * file may hold several properties) maps the name to a value > 0. */
static void parse(const char *path, const char *field, const char *const *names, List *out) {
    FILE *f = fopen(path, "r");
    char line[512];
    if (!f) { perror(path); exit(1); }
    while (fgets(line, sizeof line, f)) {
        unsigned lo, hi;
        char name[64], name2[64];
        char *p = line;
        int k, n;
        if (*p == '#' || *p == '\n') continue;
        if (sscanf(p, "%x..%x%n", &lo, &hi, &n) == 2) { /* range */ }
        else if (sscanf(p, "%x%n", &lo, &n) == 1) hi = lo;
        else continue;
        p += n;
        while (*p == ' ') p++;
        if (*p != ';') continue;
        p++;
        if (field) {
            if (sscanf(p, " %63[^ ;] ; %63[A-Za-z_]", name2, name) != 2 || strcmp(name2, field)) continue;
        } else if (sscanf(p, " %63[A-Za-z_]", name) != 1) continue;
        for (k = 0; names[k]; k++)
            if (!strcmp(names[k], name)) { add(out, lo, hi, k + 1); break; }
    }
    fclose(f);
    qsort(out->r, (size_t)out->n, sizeof(R), cmp);
}

static void emit(const char *name, const List *l) {
    int i;
    printf("const ExUcdRange %s[] = {\n", name);
    for (i = 0; i < l->n; i++)
        printf("    {0x%X, 0x%X, %d},%s", l->r[i].lo, l->r[i].hi, l->r[i].v, i % 3 == 2 ? "\n" : " ");
    printf("\n};\nconst int %s_count = %d;\n\n", name, l->n);
}

int main(int argc, char **argv) {
    static const char *gcb[] = {"CR", "LF", "Control", "Extend", "ZWJ", "Regional_Indicator", "Prepend",
                                "SpacingMark", "L", "V", "T", "LV", "LVT", NULL};
    static const char *pict[] = {"Extended_Pictographic", NULL};
    static const char *pres[] = {"Emoji_Presentation", NULL};
    static const char *incb[] = {"Consonant", "Linker", "Extend", NULL};
    List a = {0}, b = {0}, c = {0}, d = {0};
    char path[512];
    const char *dir = argc > 1 ? argv[1] : "third_party/unicode";
    snprintf(path, sizeof path, "%s/GraphemeBreakProperty.txt", dir); parse(path, NULL, gcb, &a);
    snprintf(path, sizeof path, "%s/emoji-data.txt", dir); parse(path, NULL, pict, &b);
    snprintf(path, sizeof path, "%s/emoji-data.txt", dir); parse(path, NULL, pres, &c);
    snprintf(path, sizeof path, "%s/InCB.txt", dir); parse(path, "InCB", incb, &d);
    printf("/* Generated by tools/gen_grapheme.c from Unicode 17.0.0 data (third_party/unicode).\n"
           " * Do not edit. Values: see ExGcb and ExIncb in grapheme.c. */\n#include \"grapheme_data.h\"\n\n");
    emit("ex_ucd_gcb", &a);
    emit("ex_ucd_extpict", &b);
    emit("ex_ucd_emoji_presentation", &c);
    emit("ex_ucd_incb", &d);
    return 0;
}
